use vstd::prelude::*;

verus! {

/// Given an outer vector of non‐empty inner vectors, return a new vector whose
/// i-th entry is the first element of the i-th inner vector.
fn get_first_elements(lst: Vec<Vec<i32>>) -> (result: Vec<i32>)
    requires
        // every inner vector is non‐empty
        forall|i: nat| i < lst.len() ==> lst[i].len() > 0,
    ensures
        // result has the same length
        result.len() == lst.len(),
        // and for each i, result[i] equals the first element of lst[i]
        forall|i: nat| i < lst.len() ==> result[i] == lst[i][0],
{
    let n = lst.len();
    let mut result: Vec<i32> = Vec::with_capacity(n);
    let mut i: nat = 0;
    while i < n
        invariant
            // we never overshoot
            i <= n,
            // so far we've pushed exactly i elements
            result.len() == i,
            // and they've been the correct ones
            forall|k: nat| k < i ==> result[k] == lst[k][0],
        decreases n - i,
    {
        // grab the first element of the i-th inner vector
        let first = lst[i][0];
        result.push(first);
        i = i + 1;
    }
    result
}

} // end of `verus!`

